from dateutil.parser import parse
for s in ['2017-07-17 06:15:', '2017-07-17 06:15', '06:15:', '2017-07-17 06:15:00:', '2017-07-17 06:15: ']:
    for fz in (True, False):
        try:
            r = parse(s, fuzzy=fz)
        except Exception as e:
            r = '%s: %s' % (type(e).__name__, e)
        print(repr(s), fz, '->', r)
"
